import{_ as t,o as a,c as i,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/getting-started.md","filePath":"en/guide/getting-started.md","lastUpdated":1787921783000}'),s={name:"en/guide/getting-started.md"};function n(r,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>Welcome to ZViewer! This tutorial will guide you through the complete process from scratch: downloading, starting, logging in, creating a room, adding videos, and inviting friends to watch together.</p><hr><h2 id="browser-requirements" tabindex="-1">Browser Requirements <a class="header-anchor" href="#browser-requirements" aria-label="Permalink to &quot;Browser Requirements&quot;">​</a></h2><blockquote><p><strong>Strongly recommended to use a high-version Chromium-based browser such as Chrome / Edge (kernel 130+)</strong> to access ZViewer.</p><p>⚠️ <strong>Not recommended</strong>: Safari and Firefox — due to differences in their support for MSE / MKV / browser-side decoding and transcoding, you may encounter playback stuttering, videos failing to decode, and subtitle extraction issues.</p></blockquote><hr><h2 id="step-1-download-zviewer" tabindex="-1">Step 1: Download ZViewer <a class="header-anchor" href="#step-1-download-zviewer" aria-label="Permalink to &quot;Step 1: Download ZViewer&quot;">​</a></h2><p>ZViewer offers two ways to run: <strong>single-file version</strong> and <strong>source code version</strong>.</p><h3 id="option-1-single-file-version-recommended" tabindex="-1">Option 1: Single-file Version (Recommended) <a class="header-anchor" href="#option-1-single-file-version-recommended" aria-label="Permalink to &quot;Option 1: Single-file Version (Recommended)&quot;">​</a></h3><p>No need to install Node.js or npm. Just download and extract to run.</p><ol><li>Go to the <a href="https://github.com/Zero-wyc/ZViewer/releases" target="_blank" rel="noreferrer">ZViewer Releases page</a></li><li>Download the appropriate archive for your operating system: <ul><li><strong>Windows</strong>: Download <code>zviewer-windows-x64.zip</code></li><li><strong>Linux</strong>: Download <code>zviewer-linux-x64.tar.gz</code></li></ul></li><li>Extract to any folder (e.g., <code>D:\\ZViewer</code> or <code>~/ZViewer</code>)</li></ol><p>The extracted directory structure is as follows:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>zviewer-windows-x64/</span></span>
<span class="line"><span>├── zviewer-backend.exe     # Backend service (unified hosting of frontend pages)</span></span>
<span class="line"><span>├── zviewer-cert.exe        # SSL certificate tool</span></span>
<span class="line"><span>├── start.bat               # Startup script (Windows)</span></span>
<span class="line"><span>└── start.sh                # Startup script (Linux)</span></span></code></pre></div><h3 id="option-2-source-code-version" tabindex="-1">Option 2: Source Code Version <a class="header-anchor" href="#option-2-source-code-version" aria-label="Permalink to &quot;Option 2: Source Code Version&quot;">​</a></h3><p>Suitable for users with Node.js development experience.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clone the project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Zero-wyc/ZViewer.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ZViewer</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Install dependencies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><hr><h2 id="step-2-start-the-service" tabindex="-1">Step 2: Start the Service <a class="header-anchor" href="#step-2-start-the-service" aria-label="Permalink to &quot;Step 2: Start the Service&quot;">​</a></h2><h3 id="single-file-version-startup" tabindex="-1">Single-file Version Startup <a class="header-anchor" href="#single-file-version-startup" aria-label="Permalink to &quot;Single-file Version Startup&quot;">​</a></h3><p><strong>Windows</strong>: Double-click <code>start.bat</code>, or open a terminal and run:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Interactive menu mode</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">start.bat</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or start directly</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">start.bat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> start</span></span></code></pre></div><p><strong>Linux</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>After starting, the terminal will display an interactive menu:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>========================================</span></span>
<span class="line"><span>  ZViewer Service Management</span></span>
<span class="line"><span>========================================</span></span>
<span class="line"><span>  1) Start Service (HTTP)</span></span>
<span class="line"><span>  2) Start Backend Only (HTTP / HTTPS optional)</span></span>
<span class="line"><span>  3) Stop Service</span></span>
<span class="line"><span>  4) Restart Service</span></span>
<span class="line"><span>  5) View Status</span></span>
<span class="line"><span>  6) View Logs</span></span>
<span class="line"><span>  7) One-click SSL Certificate Issuance</span></span>
<span class="line"><span>  8) HTTPS Start (Auto-issue Certificate)</span></span>
<span class="line"><span>  9) Build Frontend and Backend (Source Code Version)</span></span>
<span class="line"><span>  0) Exit</span></span></code></pre></div><p>For first-time use, select <strong>1) Start Service (HTTP)</strong>.</p><h3 id="source-code-version-startup" tabindex="-1">Source Code Version Startup <a class="header-anchor" href="#source-code-version-startup" aria-label="Permalink to &quot;Source Code Version Startup&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">start-prod.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start-prod.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Linux / macOS</span></span></code></pre></div><h3 id="access-after-starting" tabindex="-1">Access After Starting <a class="header-anchor" href="#access-after-starting" aria-label="Permalink to &quot;Access After Starting&quot;">​</a></h3><p>Once the service is running, open a browser and visit:</p><ul><li><strong>HTTP Mode</strong>: <code>http://localhost:3333</code></li><li><strong>HTTPS Mode</strong>: <code>https://localhost:3333</code></li></ul><hr><h2 id="step-3-log-in" tabindex="-1">Step 3: Log In <a class="header-anchor" href="#step-3-log-in" aria-label="Permalink to &quot;Step 3: Log In&quot;">​</a></h2><p>When the service starts for the first time, a super admin account is automatically created:</p><table tabindex="0"><thead><tr><th>Username</th><th>Password</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>root</code></td></tr></tbody></table><ol><li>Open your browser and visit <code>http://localhost:3333</code></li><li>You will see the home page. The green <strong>Connected</strong> indicator at the bottom shows the service is running normally.</li><li>Click the user avatar area in the top-right corner to log in.</li><li>Enter the username <code>root</code> and password <code>root</code>, then click &quot;Log In&quot;.</li></ol><blockquote><p>Unauthenticated users are automatically assigned a <strong>guest</strong> identity. Guests can join rooms to watch, but cannot create rooms.</p></blockquote><hr><h2 id="step-4-change-the-default-password-important" tabindex="-1">Step 4: Change the Default Password (Important!) <a class="header-anchor" href="#step-4-change-the-default-password-important" aria-label="Permalink to &quot;Step 4: Change the Default Password (Important!)&quot;">​</a></h2><p><strong>You must change the default password immediately</strong> after deploying to production, otherwise others can log into your admin panel.</p><ol><li>After logging in, click the user menu in the top-right corner (showing your username) and select &quot;Profile&quot;.</li><li>On the profile page, click the &quot;Edit Info&quot; button.</li><li>In the editing window that appears, find &quot;Change Password&quot; in the <strong>right column</strong>.</li><li>Enter the current password <code>root</code>, a new password (at least 4 characters), and confirm the new password.</li><li>Click &quot;Confirm Change&quot;.</li></ol><blockquote><p>It is also recommended to change the JWT secrets (<code>JWT_ACCESS_SECRET</code> and <code>JWT_REFRESH_SECRET</code>). See <a href="/en/dev/env">Environment Variables</a>.</p></blockquote><hr><h2 id="step-5-create-a-room" tabindex="-1">Step 5: Create a Room <a class="header-anchor" href="#step-5-create-a-room" aria-label="Permalink to &quot;Step 5: Create a Room&quot;">​</a></h2><ol><li>After changing the password, return to the home page (click the ZViewer icon in the top-left or the navigation bar).</li><li>Click the <strong>&quot;Start Sharing&quot;</strong> button.</li><li>You will enter the room page. Since there is no room ID yet, the <strong>room creation panel</strong> will be displayed.</li><li>Select a room mode: <ul><li><strong>Watch Together</strong>: Everyone watches the same video synchronously.</li><li><strong>Screen Share</strong>: The sharer broadcasts their screen.</li></ul></li><li>After creation, the page automatically enters the room.</li></ol><blockquote><p>If the &quot;Start Sharing&quot; button is disabled, it means the admin has set &quot;Only admins can create rooms&quot;. Contact the admin or log in with the <code>root</code> account.</p></blockquote><hr><h2 id="step-6-get-to-know-the-room-interface" tabindex="-1">Step 6: Get to Know the Room Interface <a class="header-anchor" href="#step-6-get-to-know-the-room-interface" aria-label="Permalink to &quot;Step 6: Get to Know the Room Interface&quot;">​</a></h2><p>After entering the room, you will see the following layout:</p><h3 id="top-area" tabindex="-1">Top Area <a class="header-anchor" href="#top-area" aria-label="Permalink to &quot;Top Area&quot;">​</a></h3><ul><li><strong>Back Button</strong>: Exit the room.</li><li><strong>Room Name</strong>: Displays the current room name. The host can click to edit it.</li><li><strong>Mode Switch</strong>: Switch between <code>Watch Together</code> / <code>Screen Share</code> (available to the host).</li></ul><h3 id="middle-area" tabindex="-1">Middle Area <a class="header-anchor" href="#middle-area" aria-label="Permalink to &quot;Middle Area&quot;">​</a></h3><ul><li><strong>Player</strong>: The video playback area, occupying most of the screen.</li></ul><h3 id="bottom-control-card-three-column-grid" tabindex="-1">Bottom Control Card (Three-column Grid) <a class="header-anchor" href="#bottom-control-card-three-column-grid" aria-label="Permalink to &quot;Bottom Control Card (Three-column Grid)&quot;">​</a></h3><ul><li><strong>Room Info</strong> (Left): Displays the room number, share link, viewer list, and permission settings.</li><li><strong>Video List</strong> (Middle): Videos added to the current room.</li><li><strong>Add Video</strong> (Right): Add videos from various sources.</li></ul><h3 id="right-panel" tabindex="-1">Right Panel <a class="header-anchor" href="#right-panel" aria-label="Permalink to &quot;Right Panel&quot;">​</a></h3><ul><li><strong>Comments / Danmaku / Chat</strong>: Real-time interaction with viewers.</li></ul><hr><h2 id="step-7-invite-friends" tabindex="-1">Step 7: Invite Friends <a class="header-anchor" href="#step-7-invite-friends" aria-label="Permalink to &quot;Step 7: Invite Friends&quot;">​</a></h2><p>After creating your room, share the room number with your friends:</p><ol><li>In the room, locate the <strong>Room Info Panel</strong> at the bottom-left.</li><li>Switch to the &quot;Info&quot; tab.</li><li>You will see: <ul><li><strong>Room Number</strong>: A numeric ID (e.g., <code>123456</code>).</li><li><strong>Share Link</strong>: A complete link you can copy and send to friends.</li></ul></li><li>Click the copy button next to the room number or link and send it to your friends.</li></ol><p>Friends can join using the following methods:</p><p><strong>Method 1: By Room Number</strong></p><ol><li>On the home page, click the &quot;Join Room&quot; button.</li><li>Enter the room number and click &quot;Join&quot;.</li></ol><p><strong>Method 2: Via Room List</strong></p><ol><li>On the home page, click the &quot;Room List&quot; button.</li><li>Find your room in the list and click &quot;Join Room&quot;.</li></ol><p><strong>Method 3: Via Share Link</strong></p><ol><li>Open the shared link directly.</li></ol><blockquote><p>If the room has a password set, friends will need to enter it when joining. If &quot;Approval Required&quot; is enabled, the host will receive a join request notification and must click &quot;Accept&quot;.</p></blockquote><hr><h2 id="step-8-add-a-video" tabindex="-1">Step 8: Add a Video <a class="header-anchor" href="#step-8-add-a-video" aria-label="Permalink to &quot;Step 8: Add a Video&quot;">​</a></h2><p>After creating the room, you need to add a video to start watching.</p><ol><li>In the room interface, find the <strong>&quot;Add Video&quot; Panel</strong> at the bottom-right.</li><li>Select your desired video source:</li></ol><h3 id="using-a-bilibili-video-most-common" tabindex="-1">Using a Bilibili Video (Most Common) <a class="header-anchor" href="#using-a-bilibili-video-most-common" aria-label="Permalink to &quot;Using a Bilibili Video (Most Common)&quot;">​</a></h3><ol><li>In the &quot;Add Video&quot; panel, select the <strong>Bilibili</strong> tab.</li><li>Paste a Bilibili video link, BV number, or AV number. <ul><li>Example: <code>https://www.bilibili.com/video/BV1GJ411x7o</code> or <code>BV1GJ411x7o</code></li></ul></li><li>Click the parse button and wait for parsing to complete.</li><li>Once parsed successfully, the video will be automatically added to the video list.</li></ol><h3 id="using-a-direct-mp4-link" tabindex="-1">Using a Direct MP4 Link <a class="header-anchor" href="#using-a-direct-mp4-link" aria-label="Permalink to &quot;Using a Direct MP4 Link&quot;">​</a></h3><ol><li>Select the <strong>Direct Link</strong> tab.</li><li>Enter the direct URL of the video file (e.g., <code>https://example.com/video.mp4</code>).</li><li>Click &quot;Add&quot;.</li></ol><h3 id="using-webdav-ftp-mounts" tabindex="-1">Using WebDAV / FTP Mounts <a class="header-anchor" href="#using-webdav-ftp-mounts" aria-label="Permalink to &quot;Using WebDAV / FTP Mounts&quot;">​</a></h3><ol><li>First configure the mount points in your profile page or admin panel.</li><li>In the &quot;Add Video&quot; panel, select the corresponding mount tab.</li><li>Browse the directory, find the video file, and click to play.</li></ol><hr><h2 id="step-9-start-watching" tabindex="-1">Step 9: Start Watching <a class="header-anchor" href="#step-9-start-watching" aria-label="Permalink to &quot;Step 9: Start Watching&quot;">​</a></h2><p>After adding the video, everything is ready!</p><ul><li><strong>Host</strong>: Click a video in the list to start playback. Playback controls (play, pause, seek, speed) are synced to all viewers in real time.</li><li><strong>Viewers</strong>: After joining the room, the player automatically syncs to the host&#39;s playback progress without any action needed.</li><li><strong>Danmaku</strong>: Send danmaku from the right panel, or load official Bilibili danmaku.</li><li><strong>Comments</strong>: Chat in the comments section to communicate with friends in real time.</li><li><strong>Subtitles</strong>: The video supports native subtitle rendering, with auto-detection, auto-adding, or manual loading of subtitle files (supports SRT, ASS, and other formats).</li></ul><hr><h2 id="port-reference" tabindex="-1">Port Reference <a class="header-anchor" href="#port-reference" aria-label="Permalink to &quot;Port Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>Port</th><th>Description</th></tr></thead><tbody><tr><td>Backend Service (Unified Entry)</td><td>3333</td><td>HTTP / HTTPS API, WebSocket, frontend static files, SPA fallback</td></tr><tr><td>RTMP Streaming</td><td>3334</td><td>OBS streaming port (separate port; RTMP is a TCP binary protocol and cannot be multiplexed with HTTP)</td></tr><tr><td>HTTP-FLV Playback</td><td>3335</td><td>Live stream playback (Node Media Server, proxied through the backend <code>/live</code> endpoint)</td></tr></tbody></table><p>In HTTP mode, users access all features at <code>http://localhost:3333</code>.</p><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Learn about <a href="/en/features/rooms">detailed room settings</a> -- passwords, viewer permissions, approval, etc.</li><li>Explore <a href="/en/features/video-sources">more video sources</a> -- Bilibili premium, WebDAV, FTP, etc.</li><li>Configure <a href="/en/guide/https">HTTPS and certificates</a> -- so the browser no longer says &quot;Not Secure&quot;.</li><li>Read the <a href="/en/admin/admin-panel">admin panel documentation</a> -- user management, room management, system settings.</li></ul>`,90)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
